        "Organizations searching for BIS ISO 9001 Certification, BIS ISO 14001 Certification, BIS ISO 22000 Certification, BIS ISO 45001 Certification, BIS ISO 50001 Certification, BIS ISO 13485 Certification, or BIS ISO 27001 Certification should first verify whether the relevant standard and certification scheme are currently offered by BIS. Not every ISO management system standard is automatically a BIS certification scheme. Certification scope, applicable standard edition, eligibility, audit requirements, and other conditions must be checked against the current BIS requirements.",
