        "In India, the Bureau of Indian Standards (BIS) acts as the national WMI coordinator. WMI codes are assigned through the international process administered by SAE International, USA, after which BIS issues the WMI code to eligible vehicle manufacturers in India. The WMI system follows the relevant international framework, including ISO 3780, while VIN structure is addressed by ISO 3779.",
        "WMI Code Registration is relevant to eligible vehicle manufacturers producing or assembling vehicles that require identification under the applicable vehicle identification and regulatory requirements. Depending on the vehicle category and applicable regulations, this may include manufacturers of passenger vehicles, commercial vehicles, motorcycles, scooters, three-wheelers, electric vehicles, and other covered road vehicles.",
        "Eminence Global Compliance Group provides WMI Registration Consultancy in India to help eligible vehicle manufacturers understand the application procedure, documentation requirements, and applicable BIS process. Our support includes application documentation preparation, coordination with BIS officials, and assistance in understanding the requirements for new vehicle varieties, additional manufacturing plants, plant address changes, or plant name changes, where applicable."
